<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/schema.php';$schema=dental_schema($pdo);$labId=$schema->labId();$serviceCol=$schema->serviceId();$serviceName=$schema->serviceName();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$published=$schema->status('valide');
$q=trim((string)($_GET['q']??''));$city=trim((string)($_GET['ville']??''));$serviceFilter=filter_var($_GET['service']??'',FILTER_VALIDATE_INT);if(!$serviceFilter||$serviceFilter<1)$serviceFilter=null;$page=max(1,(int)($_GET['page']??1));$perPage=9;
$cities=$pdo->prepare('SELECT DISTINCT ville FROM laboratoire WHERE statut=? AND ville<>\'\' ORDER BY ville');$cities->execute([$published]);$cities=$cities->fetchAll(PDO::FETCH_COLUMN);
$sql="SELECT DISTINCT s.`$serviceCol` id,s.`$serviceName` nom FROM service s JOIN laboratoire_service ls ON ls.service_id=s.`$serviceCol` JOIN laboratoire l ON l.`$labId`=ls.laboratoire_id WHERE l.statut=? ORDER BY s.`$serviceName`";$stmt=$pdo->prepare($sql);$stmt->execute([$published]);$services=$stmt->fetchAll();
$where=['l.statut=?'];$params=[$published];if($q!==''){$where[]='(l.nom_laboratoire LIKE ? OR l.ville LIKE ? OR l.adresse LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term);}if($city!==''){$where[]='l.ville=?';$params[]=$city;}if($serviceFilter){$where[]='EXISTS(SELECT 1 FROM laboratoire_service sf WHERE sf.laboratoire_id=l.`'.$labId.'` AND sf.service_id=?)';$params[]=$serviceFilter;}$whereSql=implode(' AND ',$where);
$count=$pdo->prepare('SELECT COUNT(*) FROM laboratoire l WHERE '.$whereSql);$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$sql="SELECT l.`$labId` id,l.nom_laboratoire,l.ville,l.adresse,l.description,(SELECT i.`$imagePath` FROM image_laboratoire i WHERE i.laboratoire_id=l.`$labId` ORDER BY i.`$imageId` LIMIT 1) photo,GROUP_CONCAT(DISTINCT s.`$serviceName` ORDER BY s.`$serviceName` SEPARATOR '|') services FROM laboratoire l LEFT JOIN laboratoire_service ls ON ls.laboratoire_id=l.`$labId` LEFT JOIN service s ON s.`$serviceCol`=ls.service_id WHERE $whereSql GROUP BY l.`$labId` ORDER BY l.`$labId` DESC LIMIT $perPage OFFSET $offset";$stmt=$pdo->prepare($sql);$stmt->execute($params);$labs=$stmt->fetchAll();$queryParams=[];if($q!=='')$queryParams['q']=$q;if($city!=='')$queryParams['ville']=$city;if($serviceFilter)$queryParams['service']=$serviceFilter;$pageUrl=static fn(int $p):string=>'laboratoires.php?'.http_build_query($queryParams+['page'=>$p]);
$pageTitle='Annuaire des laboratoires — DentalLink';$pageDescription='Recherchez des laboratoires de prothèses dentaires au Maroc par ville et spécialité.';$pageStyles=['assets/css/public.css'];$loadInterFont=true;require __DIR__.'/includes/header.php';require_once __DIR__.'/includes/public-nav.php';
?><main><section class="page-hero"><div class="container"><div class="breadcrumb"><a href="index.php">Accueil</a>　›　Annuaire</div><h1>Laboratoires dentaires</h1><p>Trouvez un partenaire professionnel selon sa ville et ses spécialités.</p></div></section><section class="directory"><div class="container"><form class="filter-panel" action="laboratoires.php" method="get"><input type="search" name="q" value="<?=e($q)?>" placeholder="Nom, ville ou adresse" aria-label="Rechercher par nom"><select name="ville" aria-label="Filtrer par ville"><option value="">Toutes les villes</option><?php foreach($cities as $c):?><option value="<?=e($c)?>" <?=$city===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><select name="service" aria-label="Filtrer par service"><option value="">Tous les services</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$serviceId===(int)$s['id']?'selected':''?>><?=e($s['nom'])?></option><?php endforeach;?></select><button class="btn btn-primary" type="submit">Filtrer</button><a class="btn btn-soft" href="laboratoires.php">Réinitialiser</a></form><div class="result-row"><span><?=number_format($total,0,',',' ')?> laboratoire<?=($total>1?'s':'')?> trouvé<?=($total>1?'s':'')?></span><?php if($total):?><span>Page <?=$page?> sur <?=$pages?></span><?php endif;?></div><?php if($labs):?><div class="cards"><?php foreach($labs as $lab):?><article class="lab-card"><img class="lab-photo" src="<?=e($lab['photo']?:'assets/images/lab-placeholder.svg')?>" alt="Laboratoire <?=e($lab['nom_laboratoire'])?>"><div class="lab-content"><h2 class="lab-title"><?=e($lab['nom_laboratoire'])?></h2><div class="lab-location">⌖ <?=e($lab['ville'])?> · <?=e($lab['adresse'])?></div><p class="lab-description"><?=e(text_excerpt((string)($lab['description']??''),130))?></p><div class="chips"><?php foreach(array_slice(explode('|',(string)$lab['services']),0,4) as $svc):?><?php if($svc!==''):?><span class="chip"><?=e($svc)?></span><?php endif;?><?php endforeach;?></div><a class="card-link" href="laboratoire-details.php?id=<?=$lab['id']?>">Voir le laboratoire →</a></div></article><?php endforeach;?></div><?php if($pages>1):?><nav class="pagination" aria-label="Pagination des laboratoires"><?php if($page>1):?><a class="page-link" href="<?=e($pageUrl($page-1))?>" aria-label="Page précédente">‹</a><?php endif;?><?php for($n=max(1,$page-2);$n<=min($pages,$page+2);$n++):?><a class="page-link <?=$n===$page?'active':''?>" href="<?=e($pageUrl($n))?>" <?=$n===$page?'aria-current="page"':''?>><?=$n?></a><?php endfor;?><?php if($page<$pages):?><a class="page-link" href="<?=e($pageUrl($page+1))?>" aria-label="Page suivante">›</a><?php endif;?></nav><?php endif;?><?php else:?><div class="empty"><span class="service-icon">⌕</span><h2>Aucun laboratoire trouvé</h2><p>Essayez d’autres critères ou réinitialisez les filtres.</p><a class="btn btn-primary" href="laboratoires.php">Voir tous les laboratoires</a></div><?php endif;?></div></section></main><?php require_once __DIR__.'/includes/public-footer.php'; ?></body></html>
